bool DeviceDataBase :: CheckSelectedDeviceExists(int DeviceID)
{
    bool result;
    char *tempString = "SELECT EXISTS(SELECT * FROM devices WHERE idpk=$1)";
    const char *paramValues[1];
    char str[16];

    snprintf(str, 16, "%d", DeviceID);  
    paramValues[0] = str; 

    res = PQexecParams(conn, tempString, 1, NULL, paramValues, NULL, NULL, 0);     
    
    if (PQresultStatus(res) != PGRES_TUPLES_OK) 
    {
        EventLogger :: SaveEvent() << "No data retrieved from data base";        
        PQclear(res);
	    PQfinish(conn);
    }
    
    if(strcmp(PQgetvalue(res, 0, 0), "t") == 0)
    {
        result = true;
    }
    else
    {
        result = false;
    }
    

    PQclear(res);
    return result;
}


unsigned char DeviceDataBase :: GetDataSelectedDevice(int DeviceID, Parser::config_set *deviceData)
{
    unsigned char result = 0;
    char *tempString = "SELECT * FROM devices WHERE idpk=$1";
    const char *paramValues[1];
    char str[16];
    struct tm tm;

    snprintf(str, 16, "%d", DeviceID);  
    paramValues[0] = str; 

    res = PQexecParams(conn, tempString, 1, NULL, paramValues, NULL, NULL, 0);     
    
    if (PQresultStatus(res) != PGRES_TUPLES_OK) 
    {
        EventLogger :: SaveEvent() << "No data retrieved from data base";       
        PQclear(res);
	    PQfinish(conn);
    }

    deviceData->id = atoi(PQgetvalue(res, 0, 0));
    deviceData->mac_addr = string(PQgetvalue(res, 0, 1));
    deviceData->data_port = atoi(PQgetvalue(res, 0, 2));
    deviceData->control_port = atoi(PQgetvalue(res, 0, 3));
    strptime(PQgetvalue(res, 0, 4), "%H:%M:%S", &tm);
    deviceData->creation_date = mktime(&tm);
    strptime(PQgetvalue(res, 0, 5), "%H:%M:%S", &tm);
    deviceData->expiration_date = mktime(&tm);
    deviceData->code = string(PQgetvalue(res, 0, 6));
    deviceData->who = string(PQgetvalue(res, 0, 7));
    deviceData->cards = atoi(PQgetvalue(res, 0, 8));
    for(int i = 0; i < deviceData->cards; i++)
    {
        deviceData->card_name[i] = string(PQgetvalue(res, 0, 9 + i));
    }
    deviceData->firstmess = atoi(PQgetvalue(res, 0, 14));
    deviceData->longitude = atof(PQgetvalue(res, 0, 15));
    deviceData->latitude = atof(PQgetvalue(res, 0, 16));
    deviceData->height = atoi(PQgetvalue(res, 0, 17));

    PQclear(res);

    return result;
}


unsigned char DeviceDataBase :: GetDevicesNum(void)
{
    unsigned char result = 0;
    int rows;
    int cols;

    res = PQexec(conn, "SELECT * FROM devices");

    if(PQresultStatus(res) == PGRES_TUPLES_OK)
    {
        rows = PQntuples(res);
        cols = PQnfields(res);
        numberOfElementsInDB = rows;
    }
    else if(PQresultStatus(res) == PGRES_COMMAND_OK)
    {
        EventLogger :: SaveEvent() << "DeviceDataBase::GetDevicesNum: Database is empty";
    }
    else
    {
        EventLogger :: SaveEvent() << "DeviceDataBase::GetDevicesNum: " + string(PQerrorMessage(conn));
    }
    PQclear(res);

    return result;
}


bool DeviceDataBase::LoadLicense(const char * license, uint32_t bytes, const char * pathToKey, Parser::config_set *devPar)
{
    bool result = false;
    Encryptor *encryptor = new Encryptor;

    result = encryptor->setKeyFromFile(pathToKey);
    if(result)
    {
        result = encryptor->decryptBuffer(license,bytes, devPar);
        if(result)
        {
            //EventLogger :: SaveEvent() << "License file loaded successully";
        }
        else
        {
            EventLogger :: SaveEvent() << "DeviceDataBase: could not load license from the given buffer";
        }
    }
    else
    {
        EventLogger :: SaveEvent() << "DeviceDataBase: could not read license encrypting key from the given path: " + string(pathToKey);
    }

    delete encryptor;
    
    return result;
}

